--region global define
local checkNumber = checkNumber
--endregion

--region import
---@type Engine.Lib.KTool
local KTool                    = CS.Engine.Lib.KTool
---@type MaidCoffeeConstants
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
---@type MaidCoffeeUtils
local MaidCoffeeUtils = import("Game.MaidCoffee.MaidCoffeeUtils")
--endregion

--region define
local BottomStatus = {
    Lock         = 1,  --- 猫球未解锁
    ImproveLevel = 2,  --- 猫球提升等级
    ImproveStar  = 3,  --- 猫球提升星级
    MaxStar      = 4,  --- 最大星级
}
--endregion

--- from: Assets/BundleResources/Prefabs/OverseaManage/OverseaManageCatballControlDialog.prefab
---@class OverseaManageCatBallCultivate
---@field Env                           	OverseaManageCatBallCultivate           
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TextNameMaxStar               	UnityEngine.UI.Text                     
---@field MaxStar                       	UnityEngine.RectTransform               
---@field TextNameLock                  	UnityEngine.UI.Text                     
---@field Lock                          	UnityEngine.RectTransform               
---@field FontStyleButton2              	UnityEngine.RectTransform               
---@field Improve                       	UnityEngine.RectTransform               
---@field SkillDesc                     	UnityEngine.RectTransform               
---@field ImgLock                       	UnityEngine.Animation                   
---@field BtnLock                       	UnityEngine.RectTransform               
---@field TextName                      	UnityEngine.UI.Text                     
---@field Name                          	UnityEngine.RectTransform               
---@field ImgGoodsIcon                  	Engine.UI.ImageAlterable                
---@field TextNumber                    	TMPro.TextMeshProUGUI                   
---@field IconNode                      	UnityEngine.RectTransform               
local OverseaManageCatBallCultivate = Class('OverseaManageCatBallCultivate')

function OverseaManageCatBallCultivate:__init()
    self._selectIndex = 1
end

function OverseaManageCatBallCultivate:__delete()

end

function OverseaManageCatBallCultivate:Awake()
    self._maxStar = MaidCoffeeUtils.CalcCatRollMaxStar()
end

function OverseaManageCatBallCultivate:Start()
    SetButtonAction(self.FontStyleButton2.gameObject, Bind(self, self.OnClickBtnAction))
end

function OverseaManageCatBallCultivate:OnDestroy()

    self.controller = nil--luabehaviour 中CSharp
    self:Delete()
    self = nil
end

--region init

--endregion


--region logic

---FreshUI
---@param data table{
--- vo
--- catData
--- quality
---}
---@param context OverseaManageCatBallControlDialog
function OverseaManageCatBallCultivate:FreshUI(context, isInit)
    self._context = context
    self:ReloadUI(true)
end

function OverseaManageCatBallCultivate:ReloadUI(isInit)
    local dataList = self._context:GetCatRollCultivateList()
    local data = dataList[self._selectIndex]

    ---@type MaidCoffeeCatRollConfigVo
    local vo      = data.vo
    local catData = data.catData
    self._data = data

    self.TextName.text = vo.name
        
    local count = self._context:GetThemeCatRollCount()
    
    self.TextNumber.text = string.format('%g%%', (count / #dataList) * 100)

    self:FreshSkillDesc(catData, vo)

    self:FreshStatusBottom(catData, vo)

    self._context:LoadCatModelAsync(data, isInit)
end


function OverseaManageCatBallCultivate:FreshSkillDesc(catData, vo)
    ---@type OverseaManageCatBallSkillDescNode
    local env = CfUtils.GetLuaScr(self.SkillDesc, MaidCoffeeConstants.EnvPath.OverseaManageCatBallSkillDescNode)
    if env then
        env:FreshUI(catData, vo)
    end
end

function OverseaManageCatBallCultivate:FreshStatusBottom(catData, vo)
    local status = self:GetBottomStatus(catData)
    self._bottomStatus = status
    KTool.SetActive(self.Improve.gameObject, status == BottomStatus.ImproveStar or status == BottomStatus.ImproveLevel)
    KTool.SetActive(self.Lock.gameObject,    status == BottomStatus.Lock)
    KTool.SetActive(self.MaxStar.gameObject, status == BottomStatus.MaxStar)
    
end


--endregion


--region get/set

function OverseaManageCatBallCultivate:GetSelectIndex()
    return self._selectIndex
end
function OverseaManageCatBallCultivate:SetSelectIndex(index)
    if self._selectIndex == index then
        return
    end
    local oldIndex = self._selectIndex
    self._selectIndex = index
    self:ReloadUI()
    return oldIndex
end

function OverseaManageCatBallCultivate:GetBottomStatus(catData)
    local isLock = catData == nil
    local status
    if isLock then
        status = BottomStatus.Lock
    else
        local star  = checkNumber(catData.star)
        local isMaxStar = star == self._maxStar
        if isMaxStar then
            status = BottomStatus.MaxStar
        else
            ---@type MaidCoffeeCatRollStarVo
            local starVo     = MaidCoffeeUtils.GetMaidCoffeeCatRollStarVo(math.min(star + 1, self._maxStar))
            local levelLimit = starVo.rank
            status = checkNumber(catData.level) < levelLimit and BottomStatus.ImproveLevel or BottomStatus.ImproveStar
        end
    end
   return status
end

--endregion


--region handler

function OverseaManageCatBallCultivate:OnClickBtnAction()
    if self._bottomStatus == BottomStatus.ImproveLevel then
        CfUtils.DialogOpen(Constants.UITypeIds.OverseaManageCatballLevelupPopup, {data = self._data}, nil, true)
    elseif self._bottomStatus == BottomStatus.ImproveStar then
        CfUtils.DialogOpen(Constants.UITypeIds.OverseaManageCatballStarupPopup, {data = self._data}, nil, true)
    end
end

--endregion

return OverseaManageCatBallCultivate